const body = $input.first().json;
const texto = (body.texto || '').trim();
const t = texto.toLowerCase();

if (!texto) {
  return [{ json: { error: 'Texto vacío', ok: false } }];
}

// Detectar intención
let intencion = 'consulta';
if (t.match(/quiero|pedir|necesito|manda|env[ií]a|dame|pedido|comprar|encarg/)) intencion = 'pedido';
else if (t.match(/estado|donde|cuando|llega|mi pedido|ped-/)) intencion = 'estado_pedido';
else if (t.match(/precio|cu[aá]nto|cuesta|vale|coste/)) intencion = 'precio';
else if (t.match(/stock|quedan|hay|disponible|tienes/)) intencion = 'stock';

// Detectar número de pedido mencionado
const pedidoMencionado = (texto.match(/PED-\d+/i) || [])[0] || null;

// Extraer items con cantidad
const patronCantidad = /(\d+)\s*(?:x|de|uds?|unidades?|piezas?)?\s*([a-záéíóúñA-ZÁÉÍÓÚÑ0-9\s\-\/]{3,50})/gi;
const itemsEncontrados = [];
let match;
while ((match = patronCantidad.exec(texto)) !== null) {
  const cantidad = parseInt(match[1]);
  const producto = match[2].trim().replace(/\s+/g, ' ');
  if (cantidad > 0 && cantidad < 1000 && producto.length > 2) {
    itemsEncontrados.push({ cantidad, descripcion: producto });
  }
}

// Extraer teléfono si viene
const telMatch = texto.match(/(?:\+34|0034)?\s*[6789]\d{8}/);
const telefono = telMatch ? telMatch[0].replace(/\s/g, '') : (body.telefono || '');

return [{ json: {
  ok: true,
  intencion,
  texto_original: texto,
  telefono,
  nombre: body.nombre || '',
  items_detectados: itemsEncontrados,
  pedido_mencionado: pedidoMencionado,
  timestamp: new Date().toISOString()
}}];

const d = $input.first().json;
const numeroPedido = 'PED-' + Date.now();
const items = d.items_detectados.map(item => ({
  referencia: 'PENDIENTE',
  nombre: item.descripcion,
  cantidad: item.cantidad,
  precio_unit: 0,
  subtotal: 0
}));
return [{ json: {
  numero_pedido: numeroPedido,
  telefono: d.telefono,
  nombre_cliente: d.nombre || 'Por identificar',
  items_json: JSON.stringify(items),
  estado: 'borrador',
  fecha_pedido: d.timestamp.slice(0, 19).replace('T', ' '),
  canal: 'whatsapp_manual',
  canal_origen: 'whatsapp',
  notas: 'Parseado automáticamente. Revisar precios y referencias. Texto: ' + d.texto_original.substring(0, 200)
}}];
